// Generate a percent-encoded candidate URL string. The underlying storage must
// outlive the call; we keep it in a local std::string and pass a view.
std::string uri_storage = FUZZ_PARAM_STR();
std::string_view uri_view(uri_storage);

// Call the target. It may return nullopt on invalid encodings; caller must
// handle that (we do not assert on either outcome).
auto decoded = htmlparser::Strings::DecodePercentEncodedURL(uri_view);
(void)decoded; // exercise both success and failure paths without assuming either.

// Random 32-bit code point value (any uint32 is accepted by API).
uint32_t c = *FUZZ_PARAM(unsigned int);

// Call the target.
std::string hex = htmlparser::Strings::ToHexString(c);
(void)hex;

// Provide a random byte; function interprets it as ASCII byte.
char c = static_cast<char>(*FUZZ_PARAM(unsigned int) & 0xFF);

bool is_alpha = htmlparser::Strings::IsCharAlphabet(c);
(void)is_alpha;

// Provide a random byte; function interprets it as ASCII byte.
char c = static_cast<char>(*FUZZ_PARAM(unsigned int) & 0xFF);

bool is_digit = htmlparser::Strings::IsDigit(c);
(void)is_digit;

// Build a mutable string; pointer must be non-null and valid.
std::string s = FUZZ_PARAM_STR();
// Mix in some CR characters to exercise CR/LF handling logic at bounded size.
if (!s.empty()) {
  size_t pos = (*FUZZ_PARAM(unsigned int)) % s.size();
  s.insert(pos, "\r");
  if (s.size() < 2048) s.append("\r\n");
}

htmlparser::Strings::ConvertNewLines(&s);

// Provide a raw byte; function determines expected UTF-8 sequence length.
uint8_t b = static_cast<uint8_t>(*FUZZ_PARAM(unsigned int) & 0xFF);
int8_t count = htmlparser::Strings::CodePointByteSequenceCount(b);
(void)count;

// Provide a 21-bit value (UTF-8 max is 0x10FFFF). Values outside range are
// still accepted by the API and may produce an error-indicating value.
char32_t cp = static_cast<char32_t>(*FUZZ_PARAM(unsigned int) & 0x1FFFFF);
int8_t nbytes = htmlparser::Strings::CodePointNumBytes(cp);
(void)nbytes;

// Backing storage must outlive the string_view for the duration of the call.
std::string data = FUZZ_PARAM_STR();
std::string_view sv(data);
std::size_t before = sv.size();

auto decoded = htmlparser::Strings::DecodeUtf8Symbol(&sv);
// If decoding succeeded, the cursor (sv) must advance.
if (decoded) {
  FUZZ_ASSERT(sv.size() < before, "DecodeUtf8Symbol must advance the cursor on success");
}

// Generate a code point; try to avoid surrogates to exercise success path,
// but still allow arbitrary values to exercise failure path occasionally.
uint32_t raw = *FUZZ_PARAM(unsigned int) & 0x1FFFFF; // up to 21 bits
if (raw >= 0xD800 && raw <= 0xDFFF) raw = 0x20; // map surrogates to space
char32_t cp = static_cast<char32_t>(raw);

auto enc = htmlparser::Strings::EncodeUtf8Symbol(cp);
if (enc) {
  // Property: decoding the produced bytes yields the same code point.
  std::string_view v(*enc);
  auto dec = htmlparser::Strings::DecodeUtf8Symbol(&v);
  FUZZ_ASSERT(dec && *dec == cp, "Round-trip encode/decode must match on success");
}

// Provide a UTF-8 byte sequence candidate; storage must outlive the call.
std::string utf8 = FUZZ_PARAM_STR();

auto cps = htmlparser::Strings::Utf8ToCodepoints(std::string_view(utf8));
(void)cps;

// Prepare destination string and a code point.
std::string out = FUZZ_PARAM_STR();
uint32_t raw = *FUZZ_PARAM(unsigned int) & 0x1FFFFF;
if (raw >= 0xD800 && raw <= 0xDFFF) raw = 0x2E; // '.' to avoid surrogate edge
char32_t cp = static_cast<char32_t>(raw);

htmlparser::Strings::AppendCodepointToUtf8String(cp, &out);

uint32_t raw = *FUZZ_PARAM(unsigned int) & 0x1FFFFF;
if (raw >= 0xD800 && raw <= 0xDFFF) raw = 0x41; // 'A'
char32_t cp = static_cast<char32_t>(raw);

std::string s = htmlparser::Strings::CodepointToUtf8String(cp);
if (!s.empty()) {
  // If non-empty, decoding the first symbol should equal cp.
  std::string_view v(s);
  auto dec = htmlparser::Strings::DecodeUtf8Symbol(&v);
  FUZZ_ASSERT(dec && *dec == cp, "codepointToUtf8String must produce decodable first symbol");
}

// Build a small vector of code points without using FUZZ_PARAM in a loop.
unsigned int seed = *FUZZ_PARAM(unsigned int);
unsigned int count = (seed % 8); // 0..7 code points
std::vector<char32_t> codes;
codes.reserve(count);
for (unsigned int i = 0; i < count; ++i) {
  uint32_t v = (seed ^ (0x9E3779B9u * (i + 1))) & 0x1FFFFF;
  if (v >= 0xD800 && v <= 0xDFFF) v = 0x20 + i; // avoid surrogates
  codes.push_back(static_cast<char32_t>(v));
}

std::string out = htmlparser::Strings::CodepointsToUtf8String(std::move(codes));
(void)out;

std::string s = FUZZ_PARAM_STR();
std::string chars = FUZZ_PARAM_STR();

std::size_t idx = htmlparser::Strings::IndexAny(std::string_view(s), std::string_view(chars));
(void)idx;

// Provide input storage that outlives the call.
std::string in = FUZZ_PARAM_STR();
std::string escaped = htmlparser::Strings::EscapeString(std::string_view(in));

// Property guarantee: UnescapeString(EscapeString(s)) == s.
std::string round = escaped;
htmlparser::Strings::UnescapeString(&round, /*attribute=*/false);
FUZZ_ASSERT(round == in, "UnescapeString(EscapeString(s)) must equal s");

std::string in = FUZZ_PARAM_STR();
std::stringbuf buf;
htmlparser::Strings::Escape(std::string_view(in), &buf);

// Property guarantee: UnescapeString(EscapeString(s)) == s applies; since we
// used Escape(s) into a buffer, compare after unescaping.
std::string out = buf.str();
std::string round = out;
htmlparser::Strings::UnescapeString(&round, /*attribute=*/false);
FUZZ_ASSERT(round == in, "UnescapeString(Escape(s)) must equal s");

// Start with arbitrary text, then escape it to form a valid entity string.
std::string original = FUZZ_PARAM_STR();
std::string escaped = htmlparser::Strings::EscapeString(std::string_view(original));

// Randomize attribute parsing mode.
bool attribute = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;
htmlparser::Strings::UnescapeString(&escaped, attribute);

// Regardless of attribute mode, UnescapeString(EscapeString(s)) == s.
FUZZ_ASSERT(escaped == original, "UnescapeString(EscapeString(s)) must equal s");

std::string s = FUZZ_PARAM_STR();
htmlparser::Strings::ToLower(&s);
// Optional sanity: lowercasing twice should be idempotent.
std::string t = s;
htmlparser::Strings::ToLower(&t);
FUZZ_ASSERT(t == s, "ToLower should be idempotent");

std::string s = FUZZ_PARAM_STR();
htmlparser::Strings::ToUpper(&s);
// Optional sanity: uppercasing twice should be idempotent.
std::string t = s;
htmlparser::Strings::ToUpper(&t);
FUZZ_ASSERT(t == s, "ToUpper should be idempotent");

// Choose whitespace character set: either default kWhitespace or
// kWhitespaceOrNull to exercise alternate set.
bool use_null_ws = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;
std::string in = FUZZ_PARAM_STR();
std::string_view ws = use_null_ws ? htmlparser::Strings::kWhitespaceOrNull
                                  : htmlparser::Strings::kWhitespace;

bool all_ws = htmlparser::Strings::IsAllWhitespaceChars(std::string_view(in), ws);
(void)all_ws;

// Prepare two inputs; storage must outlive the call.
std::string l = FUZZ_PARAM_STR();
std::string r = FUZZ_PARAM_STR();

// Invoke target in both orders and assert symmetry (commutativity) property.
bool lr = htmlparser::Strings::EqualFold(std::string_view(l), std::string_view(r));
bool rl = htmlparser::Strings::EqualFold(std::string_view(r), std::string_view(l));
FUZZ_ASSERT(lr == rl, "EqualFold must be symmetric");

// Prepare mutable string and non-empty search/replace tokens.
std::string s = FUZZ_PARAM_STR();
std::string f = FUZZ_PARAM_STR();
std::string t = FUZZ_PARAM_STR();
// Enforce non-empty 'f' to avoid ambiguous semantics for empty needle.
if (f.empty()) f = "x";

// Snapshot before replace to validate no-op when 'f' not found.
std::string before = s;
htmlparser::Strings::Replace(&s, std::string_view(f), std::string_view(t));

// If 'f' was not present originally, Replace must be a no-op.
if (before.find(f) == std::string::npos) {
  FUZZ_ASSERT(s == before, "Replace must be a no-op when substring not found");
}

// Prepare mutable string and non-empty search/replace tokens.
std::string s = FUZZ_PARAM_STR();
std::string f = FUZZ_PARAM_STR();
std::string t = FUZZ_PARAM_STR();
if (f.empty()) f = "x"; // enforce defined behavior

htmlparser::Strings::ReplaceAll(&s, std::string_view(f), std::string_view(t));

// After ReplaceAll, 'f' should not appear in 's'.
FUZZ_ASSERT(s.find(f) == std::string::npos, "ReplaceAll must remove all occurrences of f");

// Prepare mutable string and replacement set/target.
std::string s = FUZZ_PARAM_STR();
std::string chars = FUZZ_PARAM_STR();
std::string to = FUZZ_PARAM_STR();

htmlparser::Strings::ReplaceAny(&s, std::string_view(chars), std::string_view(to));

// Validate none of the characters in 'chars' remain in 's'.
for (unsigned char c : chars) {
  if (s.find(static_cast<char>(c)) != std::string::npos) {
    FUZZ_BAIL();
  }
}

// Prepare ASCII-only inputs to ensure valid UTF-8 when exercising identity.
std::string raw = FUZZ_PARAM_STR();
std::string str;
str.reserve(raw.size());
for (unsigned char c : raw) { str.push_back(static_cast<char>('a' + (c % 26))); }

// Build abc as unique-ish ASCII letters and xyz mapping (optionally identity).
std::string abc_raw = FUZZ_PARAM_STR();
std::string abc;
for (unsigned char c : abc_raw) { char ch = static_cast<char>('a' + (c % 26)); if (abc.find(ch) == std::string::npos) abc.push_back(ch); }
if (abc.empty()) abc = "abc"; // ensure non-empty mapping domain

bool identity = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;
std::string xyz;
if (identity) {
  xyz = abc; // identity mapping
} else {
  std::string xyz_raw = FUZZ_PARAM_STR();
  // Build a same-length xyz with ASCII letters (wrap if needed).
  for (size_t i = 0; i < abc.size(); ++i) {
    unsigned char c = (i < xyz_raw.size()) ? static_cast<unsigned char>(xyz_raw[i]) : static_cast<unsigned char>(i);
    xyz.push_back(static_cast<char>('A' + (c % 26)));
  }
}

auto out = htmlparser::Strings::Translate(std::string_view(str), std::string_view(abc), std::string_view(xyz));

// If we requested identity translation and inputs are valid ASCII, result must equal input.
if (identity) {
  FUZZ_ASSERT(out.has_value(), "Translate(identity) must succeed on ASCII inputs");
  FUZZ_ASSERT(*out == str, "Translate(identity) must be an identity mapping");
}

// Prepare string and trimming character set (use default or custom).
std::string s = FUZZ_PARAM_STR();
bool use_default = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0;
std::string chars_custom = FUZZ_PARAM_STR();
std::string_view chars = use_default ? htmlparser::Strings::kWhitespace
                                     : std::string_view(chars_custom);

htmlparser::Strings::TrimLeft(&s, chars);
// Trimming is idempotent.
std::string t = s;
htmlparser::Strings::TrimLeft(&t, chars);
FUZZ_ASSERT(t == s, "TrimLeft should be idempotent");

