import random
import string
from typing import List, Tuple

# Generator for percent-encoded URL or component strings.
# Produces valid, interesting inputs for htmlparser::Strings::DecodePercentEncodedURL.
# Constraints:
# - Return bytes (UTF-8) up to 4096 bytes.
# - Seeded randomness.

SAFE_PCHAR = string.ascii_letters + string.digits + "-._~"
SUBDELIMS = "!$&'()*+,;="
UNRESERVED = SAFE_PCHAR
HEX_DIGITS = "0123456789ABCDEF"
SCHEMES = [
    "http", "https", "ftp", "file", "ws", "wss", "gopher", "mailto",
    "data", "news", "tel", "ssh", "irc", "s3", "custom+ext", "a-b",
]

# Common path segments for variability.
SEGMENTS = [
    "", "index.html", "api", "v1", "用户", "тест", "スペース", "with space",
    "a%20b", "%2Fslashes%2F", "%E2%9C%93", "%7Ehome", "ডাটা", "пример",
]

QUERY_KEYS = [
    "q", "page", "lang", "utf8", "redirect", "token", "x", "y", "z",
]
QUERY_VALUES = [
    "test", "hello world", "a/b", "c%d", "✓", "%E2%9C%93", "%2F", "123",
    "спасибо", "数据", "~tilde", "a+b", "a%2Bb",
]

FRAGMENTS = [
    "top", "section-1", "%E2%9C%93", "with space", "Übersicht", "", "a%2Fb",
]

# Some characters to percent-encode deliberately in components
TO_ENCODE = [" ", "/", "?", "#", "%", "+", "\t", "\n"]

# Percent-encode a byte value

def pct_byte(b: int) -> str:
    return "%" + HEX_DIGITS[(b >> 4) & 0xF] + HEX_DIGITS[b & 0xF]


def pct_encode_utf8(s: str, encode_set: str = "") -> str:
    # Percent-encode given characters and non-URL-safe bytes; leave others.
    out = []
    for ch in s:
        bts = ch.encode("utf-8")
        for i, b in enumerate(bts):
            if len(bts) == 1:
                # Single-byte character
                if ch in encode_set or (ch not in UNRESERVED and ch not in SUBDELIMS and ch not in ":@/"):
                    out.append(pct_byte(b))
                else:
                    out.append(ch)
            else:
                # Multibyte UTF-8: percent-encode each byte
                out.append(pct_byte(b))
    return "".join(out)


def maybe_pct(s: str, rng: random.Random, encode_set: str = "") -> str:
    # Randomly percent-encode characters: some forced, some random.
    out = []
    for ch in s:
        if ch in encode_set or ch in TO_ENCODE or rng.random() < 0.2:
            out.append(pct_encode_utf8(ch, encode_set=encode_set or ch))
        else:
            out.append(ch)
    return "".join(out)


def gen_authority(rng: random.Random) -> str:
    # Optionally include userinfo and port. Host may be domain, IPv4, or IPv6.
    parts = []
    if rng.random() < 0.35:
        user = maybe_pct(rng.choice(["user", "admin", "测试", "πα"],), rng, encode_set=":@/")
        if rng.random() < 0.5:
            pwd = maybe_pct(rng.choice(["pass", "päss", "p%40ss"],), rng, encode_set=":@/")
            parts.append(f"{user}:{pwd}@")
        else:
            parts.append(f"{user}@")
    host_choice = rng.random()
    if host_choice < 0.6:
        # domain with labels
        labels = []
        for _ in range(rng.randint(1, 3)):
            base = rng.choice([
                "example", "sub", "svc", "xn--d1acufc", "müller"  # include unicode label
            ])
            # For domain, leave ASCII labels as-is; percent-encode unicode bytes
            labels.append(maybe_pct(base, rng))
        host = ".".join(labels)
    elif host_choice < 0.85:
        # IPv4
        host = ".".join(str(rng.randint(0, 255)) for _ in range(4))
    else:
        # IPv6 in brackets
        hextets = ["%x" % rng.randint(0, 0xFFFF) for _ in range(8)]
        host = "[" + ":".join(hextets) + "]"
    parts.append(host)
    if rng.random() < 0.4:
        parts.append(":" + str(rng.choice([80, 443, 21, 0, 65535, rng.randint(1, 65534)])))
    return "".join(parts)


def gen_path(rng: random.Random) -> str:
    # Construct a path with segments, some encoded
    segs = []
    n = rng.randint(0, 5)
    for _ in range(n):
        seg = rng.choice(SEGMENTS)
        # Introduce special chars to encode
        if rng.random() < 0.4:
            seg += rng.choice([" ", "+", "#", ";", ",", "=", ":", "@"])  # to trigger encoding
        segs.append(maybe_pct(seg, rng, encode_set="/#?+;,@"))
    path = "/" + "/".join(segs) if segs else ("/" if rng.random() < 0.6 else "")
    return path


def gen_query(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ""
    pairs = []
    m = rng.randint(1, 4)
    for _ in range(m):
        k = rng.choice(QUERY_KEYS)
        v = rng.choice(QUERY_VALUES)
        k_enc = maybe_pct(k, rng, encode_set="&=#?")
        v_enc = maybe_pct(v, rng, encode_set="&=#?")
        if rng.random() < 0.3:
            # space as + variant, keep mix of %20 and +
            v_enc = v_enc.replace(" ", "+")
        pairs.append(f"{k_enc}={v_enc}")
    return "?" + "&".join(pairs)


def gen_fragment(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ""
    frag = rng.choice(FRAGMENTS)
    frag_enc = maybe_pct(frag, rng, encode_set="#?")
    return "#" + frag_enc


def gen_full_url(rng: random.Random) -> str:
    scheme = rng.choice(SCHEMES)
    # Some schemes (mailto, data) can be special-cased
    if scheme == "mailto":
        local = maybe_pct(rng.choice(["user.name", "名-前", "δοκιμή"]), rng, encode_set="@<>#%")
        domain = rng.choice(["example.com", "δοκιμή.gr", "xn--d1acufc.xn--p1ai"])  # include puny/unicode
        return f"mailto:{local}@{domain}"
    if scheme == "data":
        mime = rng.choice(["text/plain", "text/html", "application/json", "image/png"])
        base64 = rng.random() < 0.5
        if base64:
            # simple valid base64 payload
            payload = rng.choice(["aGVsbG8=", "eyJrIjoiViJ9", "iVBORw0KGgo="])
            return f"data:{mime};base64,{payload}"
        else:
            payload = maybe_pct(rng.choice(["hello world", "<b>✓</b>", "a,b;c=d"],), rng, encode_set=",")
            return f"data:{mime},{payload}"
    # Standard hierarchical URL
    auth = gen_authority(rng)
    path = gen_path(rng)
    query = gen_query(rng)
    frag = gen_fragment(rng)
    # Some URLs start with // without explicit protocol
    if rng.random() < 0.15:
        return f"//{auth}{path}{query}{frag}"
    return f"{scheme}://{auth}{path}{query}{frag}"


def gen_component_only(rng: random.Random) -> str:
    # Generate standalone components that often include percent-encoding
    kind = rng.choice(["path", "query", "fragment", "hostname", "opaque"])  # opaque arbitrary
    if kind == "path":
        return gen_path(rng)
    if kind == "query":
        return gen_query(rng)[1:] if rng.random() < 0.7 else gen_query(rng)
    if kind == "fragment":
        return gen_fragment(rng)[1:] if rng.random() < 0.7 else gen_fragment(rng)
    if kind == "hostname":
        return gen_authority(rng)
    # opaque: a mix of unreserved, subdelims, and encoded UTF-8
    base = "".join(rng.choice(UNRESERVED + SUBDELIMS + ":@/") for _ in range(rng.randint(5, 25)))
    # Inject some unicode and spaces which we encode
    base += rng.choice([" ✓", " 数据", " تست", "\tend"])
    return maybe_pct(base, rng, encode_set=" #%")


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose between full URL and components, and occasionally a plain string already percent-encoded
    choice = rng.random()
    if choice < 0.6:
        s = gen_full_url(rng)
    elif choice < 0.9:
        s = gen_component_only(rng)
    else:
        # Raw percent-encoded sequences mixing ASCII and UTF-8 bytes
        raw = []
        length = rng.randint(10, 80)
        for _ in range(length):
            r = rng.random()
            if r < 0.5:
                raw.append(rng.choice(UNRESERVED))
            elif r < 0.8:
                # force percent-encoded byte
                raw.append(pct_byte(rng.randint(0, 255)))
            else:
                # direct UTF-8 then percent-encode bytes
                ch = rng.choice(["✓", "ß", "界", "💡", "/", "?", "#", "%"])  # include reserved
                raw.append(pct_encode_utf8(ch, encode_set=ch))
        s = "".join(raw)
    # Ensure size constraint
    b = s.encode("utf-8")
    if len(b) > 4096:
        b = b[:4096]
    return b

import random
import struct
from typing import List

# This generator focuses on producing valid and interesting UTF-8 byte sequences
# to exercise htmlparser::Strings UTF-8 related fuzzers. It mixes ASCII, multi-
# byte Unicode (2/3/4 bytes), various whitespace (including multibyte U+3000),
# punctuation, and boundary code points. It also intersperses different newline
# styles to drive newline/whitespace logic.

_MAX_BYTES = 4096

ASCII_WHITESPACE = [0x20, 0x09, 0x0A, 0x0C, 0x0D]  # space, tab, LF, FF, CR

# A selection of code points to cover a wide surface area.
# - ASCII letters/digits/punct
# - Latin-1 supplement accents
# - Greek, Cyrillic
# - Common emoji (4-byte)
# - Edge cases around plane boundaries
# - Whitespace including U+3000 IDEOGRAPHIC SPACE and NBSP
UNICODE_CODEPOINT_POOLS = {
    "ascii_letters": [ord(c) for c in ("abcdefghijklmnopqrstuvwxyz" 
                                        "ABCDEFGHIJKLMNOPQRSTUVWXYZ")],
    "ascii_digits": [ord(c) for c in "0123456789"],
    "ascii_punct": [ord(c) for c in "!@#$%^&*()-_=+[]{};:',.<>/?|\\\"`~"],
    "latin1": list(range(0x00A0, 0x00FF + 1)),
    "greek": list(range(0x0370, 0x03FF + 1)),
    "cyrillic": list(range(0x0400, 0x04FF + 1)),
    "emoji": [0x1F600, 0x1F603, 0x1F604, 0x1F601, 0x1F923, 0x1F602, 0x1F642,
               0x1F609, 0x1F60D, 0x1F680, 0x1F4A9, 0x1F44D, 0x1F44E],
    "math": list(range(0x2200, 0x22FF + 1)),
    "arabic": list(range(0x0600, 0x06FF + 1)),
    "hebrew": list(range(0x0590, 0x05FF + 1)),
    # Useful whitespace and separators
    "whitespace": [0x00A0, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
                    0x2006, 0x2007, 0x2008, 0x2009, 0x200A, 0x2028, 0x2029,
                    0x202F, 0x205F, 0x3000],  # NBSP..IDEOGRAPHIC SPACE
    # Boundary/edge scalars
    "edges": [0x007F, 0x0080, 0x07FF, 0x0800, 0xD7FF, 0xE000, 0xFFFD,
              0xFFFF, 0x10000, 0x10FFFF],
}

# Encode a Unicode scalar to UTF-8 (skip invalid scalars like surrogates)
def encode_utf8_scalar(cp: int) -> bytes:
    # Skip surrogate range explicitly
    if 0xD800 <= cp <= 0xDFFF:
        return b""
    if cp < 0 or cp > 0x10FFFF:
        return b""
    if cp <= 0x7F:
        return bytes([cp])
    elif cp <= 0x7FF:
        return bytes([0xC0 | (cp >> 6), 0x80 | (cp & 0x3F)])
    elif cp <= 0xFFFF:
        return bytes([0xE0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)])
    else:
        return bytes([0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3F),
                      0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)])

def rand_choice(rnd: random.Random, seq: List[int]) -> int:
    return seq[rnd.randrange(0, len(seq))]

def gen_ascii_word(rnd: random.Random, min_len=1, max_len=16) -> bytes:
    length = rnd.randint(min_len, max_len)
    alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    return ''.join(rnd.choice(alphabet) for _ in range(length)).encode('ascii')

def gen_utf8_word(rnd: random.Random, min_len=1, max_len=8) -> bytes:
    length = rnd.randint(min_len, max_len)
    pools = list(UNICODE_CODEPOINT_POOLS.values())
    out = bytearray()
    for _ in range(length):
        pool = rnd.choice(pools)
        cp = rand_choice(rnd, pool)
        enc = encode_utf8_scalar(cp)
        if not enc:
            # fallback to a safe ASCII letter
            enc = bytes([rand_choice(rnd, UNICODE_CODEPOINT_POOLS["ascii_letters"])])
        out.extend(enc)
    return bytes(out)

def gen_whitespace_mix(rnd: random.Random, min_runs=1, max_runs=6) -> bytes:
    runs = rnd.randint(min_runs, max_runs)
    out = bytearray()
    for _ in range(runs):
        kind = rnd.randrange(0, 5)
        if kind == 0:
            # ASCII spaces/tabs
            out.extend(bytes([rand_choice(rnd, ASCII_WHITESPACE)]) * rnd.randint(1, 5))
        elif kind == 1:
            # Windows newline CRLF
            out.extend(b"\r\n")
        elif kind == 2:
            # Classic Mac CR
            out.extend(b"\r")
        elif kind == 3:
            # U+3000 IDEOGRAPHIC SPACE
            out.extend(encode_utf8_scalar(0x3000))
        else:
            # Other Unicode space
            cp = rand_choice(rnd, UNICODE_CODEPOINT_POOLS["whitespace"]) \
                 if rnd.random() < 0.8 else 0x00A0
            out.extend(encode_utf8_scalar(cp))
    return bytes(out)

def gen_sentence(rnd: random.Random) -> bytes:
    # Build a sentence mixing ASCII and UTF-8 words with punctuation
    words = []
    n = rnd.randint(3, 12)
    for i in range(n):
        if rnd.random() < 0.5:
            w = gen_ascii_word(rnd)
        else:
            w = gen_utf8_word(rnd)
        words.append(w)
    sep = gen_whitespace_mix(rnd, 1, 2)
    sentence = sep.join(words)
    # Add terminal punctuation sometimes
    trail = rnd.choice([b".", b"!", b"?", b"", b";", b":"]) if rnd.random() < 0.8 else b""
    return sentence + trail

def gen_multiline_text(rnd: random.Random) -> bytes:
    lines = []
    count = rnd.randint(2, 8)
    for _ in range(count):
        line = gen_sentence(rnd)
        # End each line with varying newline styles
        end = rnd.choice([b"\n", b"\r\n", b"\r"]) if rnd.random() < 0.9 else b"\n"
        lines.append(line + end)
    return b"".join(lines)

def gen_emoji_run(rnd: random.Random) -> bytes:
    run = bytearray()
    n = rnd.randint(3, 16)
    for _ in range(n):
        cp = rand_choice(rnd, UNICODE_CODEPOINT_POOLS["emoji"])  # 4-byte sequences
        run.extend(encode_utf8_scalar(cp))
        if rnd.random() < 0.3:
            run.extend(gen_whitespace_mix(rnd, 1, 1))
    return bytes(run)

def gen_mixed_clusters(rnd: random.Random) -> bytes:
    # Mix scripts and edges, useful for tokenization and boundary checks
    parts = []
    for _ in range(rnd.randint(4, 12)):
        choice = rnd.random()
        if choice < 0.2:
            parts.append(gen_utf8_word(rnd, 1, 3))
        elif choice < 0.4:
            parts.append(b"-" + gen_ascii_word(rnd, 1, 5))
        elif choice < 0.6:
            # Boundary code point
            cp = rand_choice(rnd, UNICODE_CODEPOINT_POOLS["edges"])
            parts.append(encode_utf8_scalar(cp))
        elif choice < 0.8:
            parts.append(gen_whitespace_mix(rnd, 1, 2))
        else:
            parts.append(encode_utf8_scalar(rand_choice(rnd, UNICODE_CODEPOINT_POOLS["greek"])))
    return b"".join(parts)

def gen_title_like(rnd: random.Random) -> bytes:
    # Mimic a title with mixed case and multibyte spaces
    words = [gen_utf8_word(rnd, 1, 4).capitalize() for _ in range(rnd.randint(2, 6))]
    sep = rnd.choice([b" ", encode_utf8_scalar(0x3000), encode_utf8_scalar(0x2009)])
    return sep.join(words)

def gen_payload(rnd: random.Random) -> bytes:
    # Assemble a payload concatenating different segments with whitespace between
    segments = []
    builders = [gen_sentence, gen_multiline_text, gen_emoji_run, gen_mixed_clusters, gen_title_like]
    total_budget = _MAX_BYTES
    # Start with BOM sometimes (valid UTF-8 BOM)
    if rnd.random() < 0.2:
        segments.append(b"\xEF\xBB\xBF")
        total_budget -= 3
    # Ensure we generate multiple sections to exercise splitting and decoding
    for _ in range(rnd.randint(3, 8)):
        builder = rnd.choice(builders)
        part = builder(rnd)
        # Insert percent-encoded URL-ish snippet sometimes (valid text still)
        if rnd.random() < 0.3:
            # create ASCII with spaces and symbols that could be split and counted
            urlish = b"http://example.com/search?q=" + gen_ascii_word(rnd, 3, 8) + b"%20" + gen_ascii_word(rnd, 3, 8)
            part = part + b" " + urlish
        # Insert escapes and HTML-like entities to exercise CountTerms/Escape interactions
        if rnd.random() < 0.3:
            part += b" <tag attr=\"value\">&amp;&lt;&gt;\"' </tag> "
        # Bound segment size
        if len(part) > total_budget // 2:
            part = part[: max(1, total_budget // 2)]
        segments.append(part)
        total_budget -= len(part)
        if total_budget <= 0:
            break
        # Add whitespace separator between segments
        sep = gen_whitespace_mix(rnd, 1, 3)
        if len(sep) > total_budget:
            sep = sep[:total_budget]
        segments.append(sep)
        total_budget -= len(sep)
        if total_budget <= 0:
            break
    payload = b"".join(segments)
    # Final trim to max size
    if len(payload) > _MAX_BYTES:
        payload = payload[:_MAX_BYTES]
    return payload


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Randomly choose a strategy that still produces valid UTF-8 overall.
    strategy = rnd.randrange(0, 5)
    if strategy == 0:
        data = gen_multiline_text(rnd)
    elif strategy == 1:
        data = gen_emoji_run(rnd)
    elif strategy == 2:
        data = gen_mixed_clusters(rnd)
    elif strategy == 3:
        data = gen_title_like(rnd)
    else:
        data = gen_payload(rnd)
    # Ensure non-empty and within size
    if not data:
        data = b"hello\n"
    if len(data) > _MAX_BYTES:
        data = data[:_MAX_BYTES]
    return data
